'use strict';
const C=PingCore,$=s=>document.querySelector(s),KEY='ping-panda-v1';
let state,storageError=false,route='home',mode=2,showMeaning=true,showEnglish=false,answerIndex=0,rate=.85,speechToken=0,speaking=false,pauseSpeech=false,lastSpend=0;
try{const saved=localStorage.getItem(KEY);state=saved?C.validate(JSON.parse(saved)):C.fresh()}catch(e){state=C.fresh();storageError=true;}
if(state.siteLanguageVersion!==2){state.lang='en';state.siteLanguageVersion=2;}
const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const langIndex=()=>({en:0,id:1,zh:2}[state.lang]);
const t=(key,vars={})=>{let s=STRINGS[key]?.[langIndex()]||key;for(const [k,v] of Object.entries(vars))s=s.replaceAll('{'+k+'}',v);return s};
const p=()=>state.profiles.find(x=>x.id===state.active);
const nativeLang=()=>p().translationLang||'';
const nameOf=(x,type)=>x.name||DEFAULT_NAMES[type][x.key][langIndex()];
const btn=(label,action,cls='secondary',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const icons={home:'🏡',read:'📖',write:'✏️',activities:'🌈',progress:'⭐'};
function save(){rememberBook();try{localStorage.setItem(KEY,JSON.stringify(state));storageError=false}catch{storageError=true}$('#saveState').textContent=t(storageError?'saveError':'saved');}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function stop(){document.querySelectorAll('audio').forEach(a=>a.pause());speechToken++;globalThis.speechSynthesis?.cancel();speaking=false;pauseSpeech=false;document.querySelectorAll('.spoken').forEach(x=>x.classList.remove('spoken'));const b=$('[data-action="play"]');if(b)b.textContent='▶ '+t('play');const pb=$('[data-action="pause"]');if(pb)pb.disabled=true;}
function header(){document.documentElement.lang=state.lang;document.querySelectorAll('[data-i]').forEach(x=>x.textContent=t(x.dataset.i));$('#language').value=state.lang;$('#profile').innerHTML=state.profiles.map(x=>`<option value="${e(x.id)}" ${x.id===state.active?'selected':''}>${e(x.name)}</option>`).join('');$('#profileOpen').ariaLabel=t('profiles');$('.mobile-adult').ariaLabel=t('adultSpace');$('#nav').innerHTML=Object.keys(icons).map(x=>`<a href="#${x}" class="${x===route?'active':''}" ${x===route?'aria-current="page"':''}><span class="ni" aria-hidden="true">${icons[x]}</span>${t(x)}</a>`).join('');$('#saveState').textContent=t(storageError?'saveError':'saved');}
function render(){prepareBook();mode=p().level??2;header();$('#main').innerHTML=({home:homeView,read:readView,write:writeView,activities:activityView,progress:progressView,beginner:collectionPage,standard:collectionPage}[route]||homeView)();}
function navigate(){if(location.hash==='#main'){$('#main').focus();return}stop();let hash=location.hash.slice(1).split('?')[0];const params=new URLSearchParams(location.hash.split('?')[1]||'');if(BOOKS[params.get('book')]){switchBook(params.get('book'),params.get('edition')||'standard',false);if(params.has('page'))p().scene=Math.max(0,Math.min(STORY.length-1,(Number(params.get('page'))||1)-1));}route=['home','read','write','activities','progress','beginner','standard'].includes(hash)?hash:'home';render();if(hash==='books')document.getElementById('books')?.scrollIntoView({behavior:'smooth'});else window.scrollTo(0,0);}
function head(title,sub,action=''){return `<div class="page-head"><div><span class="eyebrow">${t('yourSpace')}</span><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function learningChoices(){return `<section class="learning-choices" aria-label="${t('learningSetup')}"><div class="choice-language"><div><h2>🌱 ${t('learningSetup')}</h2><p>${t('setupHelp')}</p></div><label for="translationChoice">${t('nativeLanguage')}<select id="translationChoice"><option value="">${t('chooseLanguage')}</option><option value="id" ${nativeLang()==='id'?'selected':''}>Bahasa Indonesia · Indonesian</option><option value="zh" ${nativeLang()==='zh'?'selected':''}>中文 · Mandarin Chinese</option></select></label></div><h3>${t('chooseLevel')}</h3><div class="level-grid" role="group" aria-label="${t('chooseLevel')}">${Array.from({length:5},(_,i)=>`<button data-action="mode" data-index="${i}" aria-label="${t('levelLabel',{n:i+1})}" aria-pressed="${mode===i}" class="level-option ${mode===i?'selected':''}"><span class="level-number">${i+1}</span><span class="chunk-picture" aria-hidden="true">${Array.from({length:5-i},()=>`<i style="width:${8+i*8}px"></i>`).join('')}</span><span class="level-tick" aria-hidden="true">${mode===i?'✓':'○'}</span></button>`).join('')}</div><div class="level-endpoints"><span>${t('oneWord')}</span><span>${t('fullSentence')}</span></div><p class="level-example" lang="en">${['Ping / the / Panda / was / going / to / choose / a / pet.','Ping the / Panda was / going to / choose a / pet.','Ping the Panda / was going to / choose a pet.','Ping the Panda / was going to choose / a pet.','Ping the Panda was going to choose a pet.'][mode]}</p><p class="note">${t('levelEncouragement')}</p></section>`;}
function lessonPath(){return `<section class="lesson-path" aria-label="${t('lessonPath')}">${t('lessonSteps').split('|').map((x,i)=>`<a href="#${['read','read','write','activities'][i]}"><span>${i+1}</span><strong>${x}</strong></a>`).join('')}</section><p class="note">${t('learningPurpose')}</p>`}
function homeView(){const n=p().done.length;return `${head(e(t('hello',{name:p().name})),t('welcome'))}<section class="hero"><div class="hero-copy"><div class="ping-greeting"><img src="/assets/panda.svg" alt="" width="66" height="66"><span>${t('pingSays')}</span></div><span class="pill">✦ ${t('bookLabel')}</span><h2>${t('bookTitle').replace('\n','<br>')}</h2><p>${t('bookDesc')}</p><a class="btn" href="#read">${t(n?'continue':'start')} <span aria-hidden="true">↗</span></a></div><div class="hero-art" role="img" aria-label="Ping meeting a kitten in the original watercolor illustration"><span class="art-caption">${t('originalArt')}</span></div></section>${lessonPath()}${learningChoices()}<div class="section-head"><h2>${t('nextSteps')}</h2><span>${t('atYourPace')}</span></div><div class="cards">${[['read','📖','readCard','readingSkill'],['write','✏️','writeCard','writingSkill'],['activities','🌈','activityCard','speakingSkill']].map(([r,i,d,s])=>`<a class="card card-link" href="#${r}"><div class="card-icon" aria-hidden="true">${i}</div><h3>${t(r)}</h3><p>${t(d)}</p><div class="card-foot"><span>${t(s)}</span><span aria-hidden="true">↗</span></div></a>`).join('')}</div><div class="journey"><img src="/assets/panda.svg" width="42" height="42" alt=""><div><strong>${t('journey')}</strong><p>${t('scenesDone',{n})}</p></div><div class="progress-track" role="progressbar" aria-label="${t('journey')}" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="8"><div class="progress-fill" style="width:${n/8*100}%"></div></div><span class="badge">${Math.round(n/8*100)}%</span></div><div class="story-stamps" aria-label="${t('journey')}">${SCENE_TITLES[state.lang].map((title,i)=>`<button data-action="visitScene" data-index="${i}" aria-label="${e(title)}${p().done.includes(i)?' · '+t('done'):''}" class="stamp ${p().done.includes(i)?'collected':''}"><span aria-hidden="true">${p().done.includes(i)?'⭐':'🐾'}</span><small>${i+1}</small></button>`).join('')}</div>`;}
function phraseSegments(s){const key=s.replace(/[^a-z0-9 ]/gi,'').replace(/\s+/g,' ').trim().toLowerCase();return PHRASE_MAP[key]||s.split(/(?<=,)\s+|\s+(?=and |but |with |for |to )/).filter(Boolean)}
function sentences(text){return text.match(/[^.!?]+[.!?]+[”"']?|[^.!?]+$/g)?.map(s=>s.trim()).filter(Boolean)||[text];}
function storyMarkup(){const scene=STORY[p().scene],paragraphs=scene.en.split('\n\n'),meanings=nativeLang()?scene[nativeLang()].split('\n\n'):[];let idx=0;return paragraphs.map((par,pi)=>`<section class="parallel-passage"><div class="story-text" lang="en">${sentences(par).map(sentence=>{const si=idx++;return `<p class="practice-sentence">${C.readingChunks(sentence,mode,phraseSegments).map(chunk=>`<button data-action="speakWord" data-text="${e(chunk)}" data-sentence="${si}" lang="en">${e(chunk)}</button>`).join(' <span class="chunk-divider" aria-hidden="true">/</span> ')}</p>`}).join('')}</div>${showMeaning&&nativeLang()?`<div class="meaning" lang="${nativeLang()}"><small>${t('passageMeaning')}</small><p>${e(meanings[pi]||'')}</p>${btn('♫ '+t('listenMeaning'),'passageMeaning','soft small',`data-index="${pi}"`)}</div>`:''}</section>`).join('')}
function readView(){const scene=p().scene,done=p().done.includes(scene);return `${head(t('storyName'),t('readerSub'),btn('↗ '+t('share'),'share','secondary small'))}<div class="reader-grid"><div class="reader-main">${learningChoices()}<article class="reading-card"><div class="reading-top"><div><span class="eyebrow">${t('scene')} ${scene+1} / 8</span><h2>${SCENE_TITLES[state.lang][scene]}</h2></div><span class="pill">${done?'✓': '✦'} ${t(done?'done':'draftEdition')}</span></div><div class="reading-body"><div class="button-row">${nativeLang()?btn(t(showMeaning?'hideMeaning':'meaning'),'meaning','soft small'):''}</div>${storyMarkup()}${!nativeLang()?`<p class="notice">${t('translationPrompt')}</p>`:`<p class="note">${t('translationNote')}</p>`}<div class="note">${t('modeHelp')}</div><a class="btn soft small" href="#write">${t('write')} →</a></div><div class="audio-bar">${btn('▶ '+t('play'),'play','')}${btn('Ⅱ','pause','secondary',`disabled aria-label="${t('pause')}"`)}${btn('■ '+t('stop'),'stop','secondary small')}<label><span class="sr">${t('speed')}</span><select id="rate"><option value="0.65" ${rate===.65?'selected':''}>0.65×</option><option value="0.85" ${rate===.85?'selected':''}>0.85×</option><option value="1" ${rate===1?'selected':''}>1×</option></select></label></div></article><div class="reader-actions">${btn('← '+t('previous'),'prev','secondary',scene===0?'disabled':'')}${btn((done?'✓ ':'')+t(done?'done':'markDone'),'complete',done?'soft':'')}${btn(t('next')+' →','next','secondary',scene===7?'disabled':'')}</div><p class="note">${t('voiceNote')}</p></div><aside class="reader-aside"><div class="card"><h3>${t('chapters')}</h3><div class="scene-list">${SCENE_TITLES[state.lang].map((s,i)=>`<button data-action="scene" data-index="${i}" class="${i===scene?'active':''}" ${i===scene?'aria-current="step"':''}><span class="scene-num">${p().done.includes(i)?'✓':i+1}</span>${s}</button>`).join('')}</div><p class="note">${t('readingTip')}</p>${btn(t('wholeBook'),'wholeBook','soft small')}<hr class="divider"><h3>${t('originalRecording')}</h3><p class="note">${t('recordingNote')}</p><audio controls preload="none" src="/assets/original-readthrough.mp3" aria-label="${t('originalRecording')}"></audio></div><div class="card"><span class="eyebrow">${t('originalArt')}</span><button data-action="art" aria-label="${t('originalArt')}" style="padding:0;width:100%"><img class="book-art" src="/assets/page-${scene+1}.webp" alt="${e(SCENE_TITLES.en[scene])} — original illustrated page"></button><p class="note">${t('artNote')}</p></div></aside></div>`;}
function writeView(){return `${head(t('writeTitle'),t('writeSub'))}<div class="split"><section class="card"><span class="pill">${t('storyName')}</span><div style="height:25px"></div>${t('prompts').split('|').map((q,i)=>`<div class="form-row"><label for="answer-${i}">${i+1}. ${q}</label><small lang="en">${t('frames').split('|')[i]}</small><textarea lang="en" id="answer-${i}" data-answer="${i}" maxlength="5000" placeholder="${e(t('frames').split('|')[i])}">${e(p().answers[i])}</textarea><div>${btn('♫ '+t('readWriting'),'readAnswer','soft small',`data-index="${i}"`)}</div></div>`).join('')}<label class="checks"><input type="checkbox" id="shared" ${p().shared?'checked':''}>${t('reflection')}</label><p class="notice">${t('effortFirst')}</p>${btn(t('checkWriting'),'checkWriting','')}<div id="writingFeedback" role="status"></div></section><aside class="stack"><section class="card"><div class="card-icon">✎</div><h2>${t('phraseBank')}</h2><p class="muted">${t('phraseDesc')}</p><div class="word-chips">${['I can help by ','I would choose ','because ','Today I learned ','I will '].map(s=>`<button lang="en" data-action="phrase" data-text="${e(s)}">${e(s)}</button>`).join('')}</div><p class="note">${t('readBack')}</p></section><section class="card"><h3>${t('translateLink')}</h3><p class="note">${t('translateNote')}</p><a class="btn secondary small" target="_blank" rel="noopener noreferrer" href="https://translate.google.com/?sl=auto&tl=en&op=translate">${t('translateLink')} ↗</a></section></aside></div>`;}
function stats(){const pr=p(),rev=C.reversed(pr),earned=pr.ledger.filter(x=>x.kind==='earn'&&!rev.has(x.id)).reduce((n,x)=>n+x.amount,0),days=new Set(pr.ledger.filter(x=>x.kind==='earn'&&!rev.has(x.id)).map(x=>x.date)).size;return `<div class="stat-grid"><div class="stat wallet"><strong>◉ ${C.balance(pr)}</strong><span>${t('balance')}</span></div><div class="stat"><strong>${earned}</strong><span>${t('earned')}</span></div><div class="stat"><strong>${days}</strong><span>${t('activeDays')}</span></div></div>`;}
function ledger(){return `<div class="table-wrap"><table><thead><tr><th>${t('date')}</th><th>${t('what')}</th><th>${t('change')}</th></tr></thead><tbody>${[...p().ledger].reverse().map(x=>`<tr><td>${x.date}</td><td>${x.kind==='reverse'?t('reversal')+': ':''}${e(x.label)}</td><td>${x.amount>0?'+':''}${x.amount}</td></tr>`).join('')||`<tr><td colspan="3">${t('noLedger')}</td></tr>`}</tbody></table></div>`;}
function calendar(){if(!p().start)return `<label class="form-row">${t('startDate')}<input type="date" id="startDate" value="${C.localDay()}"></label>${btn(t('startChallenge'),'startChallenge','soft')}`;const rev=C.reversed(p()),dates=new Set(p().ledger.filter(x=>x.kind==='earn'&&!rev.has(x.id)).map(x=>x.date));return `<p class="note">${t('startDate')}: ${p().start}</p><div class="calendar">${Array.from({length:30},(_,i)=>{const d=new Date(p().start+'T12:00:00');d.setDate(d.getDate()+i);const key=C.localDay(d);return `<span class="day ${dates.has(key)?'done':''} ${key===C.localDay()?'today':''} ${key>C.localDay()?'future':''}" title="${key}" aria-label="${key}${dates.has(key)?' ✓':''}">${dates.has(key)?'✓ ':''}${i+1}</span>`}).join('')}</div>`;}
function activityView(){const pr=p();return `${head(t('activityTitle'),t('activitySub'),btn(t('manage'),'manage','secondary small'))}${stats()}<p class="notice">${t('pretend')}</p><div class="split"><div class="stack"><section class="card"><h2>${t('jobs')}</h2><label class="checks no-print"><input type="checkbox" id="approved">${t('approved')}</label>${pr.jobs.map(x=>`<div class="job-row"><div><h3>${e(nameOf(x,'jobs'))}</h3><span class="coins">+${x.price} ◉</span></div>${btn(t(C.credited(pr,x.id)?'alreadyEarned':'earn'),'earn','soft small',`data-id="${x.id}" ${C.credited(pr,x.id)?'disabled':''}`)}</div>`).join('')}<p class="note">${t('onePerDay')}</p></section><section class="card"><h2>${t('shop')}</h2>${pr.rewards.map(x=>`<div class="job-row"><div><h3>${e(nameOf(x,'rewards'))}</h3><span class="coins">${x.price} ◉</span></div>${btn(t(C.balance(pr)<x.price?'notEnough':'buy'),'buy','secondary small',`data-id="${x.id}" ${C.balance(pr)<x.price?'disabled':''}`)}</div>`).join('')}</section><section class="card"><div class="section-head" style="margin-top:0"><h2>${t('ledger')}</h2>${btn('↶ '+t('undo'),'undo','secondary small',pr.ledger.length?'':'disabled')}</div>${ledger()}<p class="note">${t('undoExplain')}</p></section></div><aside class="stack"><section class="card"><h3>${t('goal')}</h3><input id="goal" type="text" maxlength="150" value="${e(pr.goal)}" placeholder="${e(t('goalPlaceholder'))}"><div class="button-row">${btn(t('saveGoal'),'saveGoal','soft small')}</div></section><section class="card"><h3>${t('month')}</h3><p class="note">${t('challengeHelp')}</p>${calendar()}</section><section class="card"><h3>${t('sayIt')}</h3><p lang="en">${t('sayPrompt')}</p><h3>${t('weekly')}</h3><ol class="guide-list">${t('weeks').split('|').map(x=>`<li>${x}</li>`).join('')}</ol></section></aside></div>`;}
function progressView(){return `${head(t('progressTitle'),t('progressSub'),btn('↗ '+t('print'),'print','secondary'))}<p class="print-only">${e(p().name)} · ${C.localDay()}</p><div class="stat-grid"><div class="stat"><strong>${p().done.length}/${STORY.length}</strong><span>${t('chapters')}</span></div><div class="stat"><strong>${p().answers.filter(x=>x.trim()).length}/3</strong><span>${t('answers')}</span></div><div class="stat"><strong>${C.balance(p())}</strong><span>${t('balance')}</span></div></div><p class="note">${t('learningNote')} ${t('printNote')}</p><div class="split"><section class="card"><h2>${t('myAnswers')}</h2>${t('prompts').split('|').map((q,i)=>`<h3>${q}</h3><p class="writing-print" lang="en">${e(p().answers[i]||t('noAnswer'))}</p>`).join('')}<p class="note">${p().shared?'✓ '+t('reflection'):''}</p></section><section class="card"><h2>${t('month')}</h2>${p().start?calendar():`<p class="note">${t('challengeHelp')}</p><a class="btn soft" href="#activities">${t('activities')} →</a>`}<hr class="divider"><h3>${t('goal')}</h3><p>${e(p().goal||'—')}</p></section></div><div class="card" style="margin-top:20px"><h2>${t('ledger')}</h2>${ledger()}</div>`;}
function modal(title,body){$('#dialogContent').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="close" data-action="close" aria-label="${t('close')}">×</button></div>${body}`;if(!$('#dialog').open)$('#dialog').showModal();}
function adult(){modal(t('adultTitle'),`<p>${t('adultGuide')}</p><p class="notice">${t('preliminaryNote')}</p>${curriculumPreview()}<p class="notice">${t('adultRules')}</p><p class="note">${t('privacy')}</p><div class="button-row">${btn(t('export'),'export','')}${btn(t('import'),'import','secondary')}${btn(t('profiles'),'profiles','soft')}</div><hr class="divider"><h3>${t('offline')}</h3><p class="note">${t('offlineHelp')}</p>${btn(t('download'),'offline','soft')}<p id="offlineStatus" class="offline-state" role="status"></p><hr class="divider"><p class="note">${t('translationNote')}<br>${t('voiceNote')}<br>${t('shareNote')}</p><small>${t('appVersion')}</small>`);}
function profiles(){modal(t('profiles'),`<div>${state.profiles.map(x=>`<div class="job-row"><strong>${e(x.name)}</strong><div>${btn(x.id===state.active?'✓':t('learner'),'selectProfile','soft small',`data-id="${x.id}"`)} ${btn(t('remove'),'removeProfile','danger small',`data-id="${x.id}"`)}</div></div>`).join('')}</div><form id="addProfile" class="inline-form"><label class="sr" for="nickname">${t('nickname')}</label><input type="text" id="nickname" name="nickname" required maxlength="40" placeholder="${t('nickname')}"><button class="btn" ${state.profiles.length>=12?'disabled':''}>${t('add')}</button></form><p class="note">${t('privacy')}</p>`);}
function manage(){modal(t('manage'),['jobs','rewards'].map(type=>`<h3>${t(type==='jobs'?'jobs':'shop')}</h3>${p()[type].map(x=>`<div class="job-row"><span>${e(nameOf(x,type))} · ${x.price} ◉</span>${btn('×','removeItem','danger small',`data-type="${type}" data-id="${x.id}" aria-label="${t('remove')} ${e(nameOf(x,type))}"`)}</div>`).join('')}<form class="inline-form addItem" data-type="${type}"><label class="sr" for="${type}-name">${t('name')}</label><input type="text" name="name" id="${type}-name" required maxlength="100" placeholder="${t(type==='jobs'?'newJob':'newReward')}"><label class="sr" for="${type}-price">${t('value')}</label><input type="number" id="${type}-price" name="price" min="1" max="1000" value="1" required><button class="btn small">${t('add')}</button></form>`).join('<hr class="divider">'));}
function voiceFor(lang){const voices=globalThis.speechSynthesis?.getVoices()||[];return voices.find(x=>x.lang.toLowerCase()===LANGS[lang].toLowerCase())||voices.find(x=>x.lang.toLowerCase().startsWith(lang==='zh'?'zh':lang));}
async function speak(text,lang='en',whole=false){stop();const token=speechToken;if(!globalThis.speechSynthesis){toast(t('voiceMissing'));return}let voice=voiceFor(lang);if(!voice){await new Promise(r=>setTimeout(r,250));voice=voiceFor(lang)}if(token!==speechToken)return;if(!voice){toast(t('voiceMissing'));return}speaking=true;const playBtn=$('[data-action="play"]');if(playBtn)playBtn.textContent='♫';const pauseBtn=$('[data-action="pause"]');if(pauseBtn)pauseBtn.disabled=false;
 const playOne=(chunk,si)=>new Promise(resolve=>{if(token!==speechToken){resolve();return}document.querySelectorAll('.spoken').forEach(x=>x.classList.remove('spoken'));if(!whole&&lang==='en')document.querySelectorAll(`[data-sentence="${si}"]`).forEach(x=>{if(x.dataset.text===chunk)x.classList.add('spoken')});const u=new SpeechSynthesisUtterance(chunk);u.lang=LANGS[lang];u.voice=voice;u.rate=rate;u.onend=resolve;u.onerror=err=>{if(token===speechToken&&err.error!=='canceled'&&err.error!=='interrupted'){toast(t('audioError'));stop()}resolve()};globalThis.speechSynthesis.speak(u);});
 const chunks=lang!=='en'?[text]:sentences(text);for(let si=0;si<chunks.length;si++){if(token!==speechToken)break;let pieces=[chunks[si]];if(lang==='en'&&!whole)pieces=C.readingChunks(chunks[si],mode,phraseSegments);for(const chunk of pieces){while(pauseSpeech&&token===speechToken)await new Promise(r=>setTimeout(r,100));if(token!==speechToken)break;await playOne(chunk,si);if(lang==='en'&&!whole&&mode<=4)await new Promise(r=>setTimeout(r,Math.max(1000,chunk.split(/\s+/).length*550)));}if(lang==='en'&&!whole&&mode===0&&token===speechToken)await playOne(chunks[si],si);}
 if(token===speechToken)stop();}
async function offline(){const status=$('#offlineStatus');status.textContent=t('downloading');try{if(!('serviceWorker'in navigator))throw Error();const reg=await navigator.serviceWorker.register('/sw.js');await navigator.serviceWorker.ready;const worker=reg.active||reg.waiting||reg.installing;if(!worker)throw Error();const channel=new MessageChannel();await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('timeout')),60000);channel.port1.onmessage=ev=>{clearTimeout(timer);ev.data.ok?resolve():reject(Error())};worker.postMessage({type:'CACHE_APP'},[channel.port2])});status.textContent=t('offlineReady')}catch{status.textContent=t('offlineFail')}}
function exportBackup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`ping-backup-${C.localDay()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function action(el){const a=el.dataset.action,i=Number(el.dataset.index),id=el.dataset.id;try{switch(a){
case 'close':$('#dialog').close();break;case 'adult':adult();break;case 'profiles':profiles();break;case 'manage':manage();break;
case 'visitScene':stop();p().scene=i;save();location.hash='read';break;case 'mode':stop();mode=i;p().level=i;showEnglish=false;save();render();break;case 'scene':stop();p().scene=i;save();render();break;case 'prev':case 'next':stop();p().scene=Math.max(0,Math.min(STORY.length-1,p().scene+(a==='prev'?-1:1)));save();render();break;
case 'meaning':stop();showMeaning=!showMeaning;render();break;case 'text':showEnglish=!showEnglish;render();break;case 'complete':if(!p().done.includes(p().scene))p().done.push(p().scene);save();render();toast('⭐ '+t('sceneCheer'));break;
case 'play':speak(STORY[p().scene].en);break;case 'wholeBook':speak(STORY.map(s=>s.en).join('\n\n'),'en',true);break;case 'stop':stop();break;case 'pause':pauseSpeech=!pauseSpeech;pauseSpeech?speechSynthesis.pause():speechSynthesis.resume();el.textContent=pauseSpeech?'▶':'Ⅱ';break;
case 'speakWord':speak(el.dataset.text,'en',true);break;case 'speakSentence':speak(el.dataset.text,'en',true);break;case 'passageMeaning':speak(STORY[p().scene][nativeLang()].split('\n\n')[i],nativeLang(),true);break;case 'speakMeaning':speak(STORY[p().scene][nativeLang()],nativeLang(),true);break;
case 'art':modal(book().title[langIndex()],`<img class="full-image" src="${artPath(p().scene)}" alt="${e(book().alt[p().scene])}"><p class="note">${book().credit}</p>`);break;
case 'readAnswer':p().answers[i].trim()?speak(p().answers[i],'en',true):toast(t('emptyWriting'));break;
case 'phrase':{const input=$('#answer-'+answerIndex);input.value+=el.dataset.text;p().answers[answerIndex]=input.value.slice(0,5000);input.value=p().answers[answerIndex];input.focus();save();break;}
case 'checkWriting':{const checks=p().answers.map((a,i)=>{const value=a.trim();const basic=value.split(/\s+/).length>=3&&/^[A-Z]/.test(value)&&/[.!?][’"']?$/.test(value);return `<li>${i+1}. ${t(!value?'emptyWriting':basic?'sentenceReady':'sentenceHelp')}</li>`});$('#writingFeedback').innerHTML=`<div class="notice"><ul>${checks.join('')}</ul><p>${t('writingCheck')}</p></div>`;break;}
case 'earn':{if(!$('#approved').checked){toast(t('approvalNeeded'));break}const item=p().jobs.find(x=>x.id===id);if(!item)break;C.transact(p(),'earn',item,nameOf(item,'jobs'));save();render();toast(t('earnedToast'));break;}
case 'buy':{if(Date.now()-lastSpend<1200)break;const item=p().rewards.find(x=>x.id===id);if(!item)break;if(!confirm(`${t('buy')}: ${nameOf(item,'rewards')} (${item.price} ◉)?`))break;lastSpend=Date.now();C.transact(p(),'spend',item,nameOf(item,'rewards'));save();render();toast(t('boughtToast'));break;}
case 'undo':if(C.undo(p())){save();render();toast(t('undoDone'))}break;
case 'saveGoal':p().goal=$('#goal').value.trim().slice(0,150);save();toast(t('goalSaved'));break;
case 'startChallenge':{const date=$('#startDate').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(date)){toast(t('invalid'));break}p().start=date;save();render();toast(t('challengeStarted'));break;}
case 'selectProfile':stop();state.active=id;save();render();profiles();break;
case 'removeProfile':if(state.profiles.length===1){toast(t('lastProfile'));break}if(confirm(t('removeAsk'))){stop();state.profiles=state.profiles.filter(x=>x.id!==id);if(state.active===id)state.active=state.profiles[0].id;save();render();profiles()}break;
case 'removeItem':p()[el.dataset.type]=p()[el.dataset.type].filter(x=>x.id!==id);save();render();manage();break;
case 'export':exportBackup();break;case 'import':$('#importFile').value='';$('#importFile').click();break;case 'offline':offline();break;case 'print':window.print();break;
case 'share':try{await navigator.clipboard.writeText(location.origin+'/#read?book='+p().book+'&page='+(p().scene+1));toast(t('copied'));modal(t('share'),`<p>${t('shareNote')}</p>`)}catch{modal(t('share'),`<input type="text" readonly value="${e(location.origin+'/#read?book='+p().book+'&page='+(p().scene+1))}"><p class="note">${t('shareNote')}</p>`)}break;
}}catch(err){toast(t(err.message in STRINGS?err.message:'invalid'))}}
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(el&&!el.disabled)action(el)});
document.addEventListener('input',ev=>{if(ev.target.dataset.answer!==undefined){const i=Number(ev.target.dataset.answer);p().answers[i]=ev.target.value;save()}});
document.addEventListener('focusin',ev=>{if(ev.target.dataset.answer!==undefined)answerIndex=Number(ev.target.dataset.answer)});
document.addEventListener('change',ev=>{if(ev.target.id==='translationChoice'){stop();p().translationLang=ev.target.value;showMeaning=true;save();render();}if(ev.target.id==='shared'){p().shared=ev.target.checked;save()}if(ev.target.id==='rate'){stop();rate=Number(ev.target.value)}});
document.addEventListener('submit',ev=>{if(ev.target.id==='addProfile'){ev.preventDefault();const name=new FormData(ev.target).get('nickname').trim();if(!name||name.length>40||state.profiles.length>=12)return;const pr=C.profile(name);state.profiles.push(pr);state.active=pr.id;stop();save();render();profiles()}if(ev.target.matches('.addItem')){ev.preventDefault();const type=ev.target.dataset.type,fd=new FormData(ev.target),name=fd.get('name').trim(),price=Number(fd.get('price'));if(!name||name.length>100||!Number.isInteger(price)||price<1||price>1000||p()[type].length>=50){toast(t('invalid'));return}p()[type].push({id:C.uid(),key:null,name,price});save();render();manage()}});
$('#language').addEventListener('change',ev=>{stop();state.lang=ev.target.value;save();render()});$('#profile').addEventListener('change',ev=>{stop();state.active=ev.target.value;save();render()});$('#adultOpen').onclick=adult;$('#profileOpen').onclick=profiles;
$('#importFile').addEventListener('change',async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error();const candidate=C.validate(JSON.parse(await file.text()));if(!confirm(t('importAsk')))return;stop();state=candidate;save();render();$('#dialog').close();toast(t('restored'))}catch{toast(t('importBad'))}});
window.addEventListener('hashchange',navigate);window.addEventListener('pagehide',stop);window.addEventListener('storage',ev=>{if(ev.key===KEY&&ev.newValue){try{stop();state=C.validate(JSON.parse(ev.newValue));render()}catch{}}});
if(storageError)toast(t('saveError'));

function curriculumPreview(){return `<details class="curriculum"><summary>${t('curriculumTitle')}</summary><p>${t('curriculumNote')}</p><ul>${t('curriculumItems').split('|').map(x=>`<li>${x}</li>`).join('')}</ul></details>`}
document.addEventListener('play',ev=>{if(ev.target.tagName==='AUDIO'){speechToken++;globalThis.speechSynthesis?.cancel();speaking=false;pauseSpeech=false;}},true);
